window.until = async (fn, ms = 8000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await new Promise((r) => setTimeout(r, 150)) } return false };
window.nav = (name) => [...document.querySelectorAll('nav button')].find((b) => b.textContent.trim() === name).click();
window.tab = async (label) => { const t = [...document.querySelectorAll('[role=tab]')].find((x) => x.textContent.trim() === label); if (!t) return 'NO TAB ' + label; t.click(); await new Promise((r) => setTimeout(r, 600)); return 'tab ' + label };
window.explore = () => ({ current: document.querySelector('nav [aria-current=page]')?.textContent, tabs: [...document.querySelectorAll('[role=tablist][aria-label=Explore] [role=tab]')].map((t) => t.textContent + (t.getAttribute('aria-selected') === 'true' ? '*' : '')), season: document.querySelector('[title=Season]')?.selectedOptions?.[0]?.textContent ?? document.querySelector('[title=Season]')?.textContent, h1: document.querySelector('main h1')?.innerText ?? null, trends: document.querySelector('[data-subject]')?.getAttribute('data-subject') ?? null });
